void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 ori=floor(fragCoord/bs)/iResolution.xy; 
    vec2 frac=fract(fragCoord/bs);

    vec4 form = texture(iChannel0, ori+vec2(0.5)/iResolution.xy);

    fragColor=form;

    //based on the information from Buffer A it draw different lines
    if (form.r>0.0){ //dia
        float dif=frac.x-frac.y; 
        fragColor=vec4(dif>-0.2 && dif<0.2); 
    }else if (form.g>0.0){ //codia
        float dif=frac.x-1.0+frac.y; 
        fragColor=vec4(dif>-0.2 && dif<0.2); 
    }else if (form.b>0.0){ //hor
        fragColor=vec4(frac.y>-0.2 && frac.y<0.2); 
    }else if (form.a>0.0 && form.a<1.0){ //ver
        fragColor=vec4(frac.x>-0.2 && frac.x<0.2); 
    }else
        fragColor=vec4(0.0);
    //gl_FragColor*=form;
    fragColor.a=1.0;
}

//this part preprocess the image, calculating once per segment of size bs x bs if the segment is diagonal, horizontal, etc

//lower treshold = more filled space
const float treshold=0.2;

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    //space per pixel
    float tx=1.0/iResolution.x; 
    float ty=1.0/iResolution.y; 

    vec2 ori=floor(fragCoord)/iResolution.xy;
    if (ori.x>1.0/bs || ori.y>1.0/bs){
        //exit for redundant info //we just caulculating 1/bs of the texture
        fragColor=vec4(ori,0.5,1.0);
        return;
    }
    vec2 frac=fract(fragCoord);

    vec4 dia=vec4(0.0);
    vec4 codia=vec4(0.0);
    vec4 hor=vec4(0.0);
    vec4 ver=vec4(0.0);
    for (float x=0.; x<1.; x+=1./bs){ 
        for (float y=0.; y<1.; y+=1./bs){
            vec2 offset = vec2(x * tx, y * ty);
            vec4 bcol=texture( iChannel0, (ori+vec2(x*tx,y*ty))*bs);

            //divides by mean color so separation between darker colors affects the same as with lighter colors
            hor += abs(bcol - texture(iChannel0, (ori + offset + vec2(0., ty))*bs)) * 3.0 / (bcol.x + bcol.y + bcol.z);
            ver += abs(bcol - texture(iChannel0, (ori + offset + vec2(tx, 0.))*bs)) * 3.0 / (bcol.x + bcol.y + bcol.z);
            dia += abs(bcol - texture(iChannel0, (ori + offset + vec2(tx, -ty))*bs)) * 3.0 / (bcol.x + bcol.y + bcol.z);
            codia += abs(bcol - texture(iChannel0, (ori + offset + vec2(tx, ty))*bs)) * 3.0 / (bcol.x + bcol.y + bcol.z);
        } 
    }

    dia/=(bs*bs);
    float diaf=(dia.x+dia.y+dia.z)/3.0; 
    codia/=(bs*bs); 
    float codiaf=(codia.x+codia.y+codia.z)/3.0; 
    hor/=(bs*bs); 
    float horf=(hor.x+hor.y+hor.z)/3.0; 
    ver/=(bs*bs); 
    float verf=(ver.x+ver.y+ver.z)/3.0;

    //substract horf and verf from the diagonals
    diaf-=(horf+verf)/4.0;
    codiaf-=(horf+verf)/4.0;

    //save a color depending on how diagonal, horizontal, etc is the segment
    if (diaf>treshold && diaf>horf && diaf>verf && diaf>codiaf){
        fragColor=vec4(1.0,0.0,0.0,1.0);
    }else if (codiaf>treshold && codiaf>horf && codiaf>verf){ 
        fragColor=vec4(0.0,1.0,0.0,1.0);
    }else if (horf>treshold && horf>verf){ 
        fragColor=vec4(0.0,0.0,1.0,1.0);
    }else if (verf>treshold){
        fragColor=vec4(0.0,0.0,0.0,0.5);
    }else
        fragColor=vec4(0.0,0.0,0.0,0.0);
}
